code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    if len(colors) != 1:
        raise ValueError("expected one nonzero color")
    color = next(iter(colors))
    mask = [[grid[r][c] == color for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(w*w)] for _ in range(h*h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                for dr in range(h):
                    for dc in range(w):
                        if not mask[dr][dc]: out[r*h+dr][c*w+dc]=color
    return out
'''; open(p,'w').write(code); exec(code); test=[[0,0,3],[3,3,0],[0,3,0]]; ans=transform(test); print(ans)
